// Read the segment targeted by commands, not a possibly stale effect-render cache.
static void getCurrentRGBW(uint8_t& r, uint8_t& g, uint8_t& b, uint8_t& w) {
  uint32_t c = strip.getMainSegment().colors[0];
  r = R(c);
  g = G(c);
  b = B(c);
  w = W(c);
}
